BEGIN;
CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','inspector','viewer')), active INTEGER NOT NULL DEFAULT 1, auth_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, auth_version INTEGER NOT NULL, last_seen REAL NOT NULL);
CREATE TABLE login_attempts(client TEXT PRIMARY KEY, failures INTEGER NOT NULL, blocked_until REAL NOT NULL);
CREATE TABLE layouts(id INTEGER PRIMARY KEY, version INTEGER NOT NULL UNIQUE, original_path TEXT NOT NULL, image_path TEXT NOT NULL, width INTEGER, height INTEGER, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE equipment(id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, type TEXT NOT NULL CHECK(type IN ('manifold','extinguisher','hydrant')), subtype TEXT, name TEXT NOT NULL, location_text TEXT NOT NULL, layout_id INTEGER NOT NULL REFERENCES layouts(id), x REAL NOT NULL CHECK(x BETWEEN 0 AND 1), y REAL NOT NULL CHECK(y BETWEEN 0 AND 1), deleted_at TEXT, deleted_by INTEGER REFERENCES users(id), delete_reason TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, CHECK(type!='hydrant' OR (subtype IS NOT NULL AND subtype IN ('indoor','outdoor'))));
CREATE TABLE assignments(id INTEGER PRIMARY KEY, equipment_id INTEGER NOT NULL REFERENCES equipment(id), year INTEGER NOT NULL, quarter INTEGER NOT NULL CHECK(quarter BETWEEN 1 AND 4), assignee_id INTEGER NOT NULL REFERENCES users(id), UNIQUE(equipment_id,year,quarter));
CREATE TABLE checklist_templates(id INTEGER PRIMARY KEY, type TEXT NOT NULL, version INTEGER NOT NULL, UNIQUE(type,version));
CREATE TABLE checklist_items(id INTEGER PRIMARY KEY, template_id INTEGER NOT NULL REFERENCES checklist_templates(id), item_code TEXT NOT NULL, label TEXT NOT NULL, applicability TEXT, UNIQUE(template_id,item_code));
CREATE TABLE inspections(id INTEGER PRIMARY KEY, equipment_id INTEGER NOT NULL REFERENCES equipment(id), year INTEGER NOT NULL, quarter INTEGER NOT NULL CHECK(quarter BETWEEN 1 AND 4), inspector_id INTEGER REFERENCES users(id), submitted_at TEXT, template_id INTEGER REFERENCES checklist_templates(id), status_at_submission TEXT, version INTEGER NOT NULL DEFAULT 1, UNIQUE(equipment_id,year,quarter));
CREATE TABLE inspection_results(id INTEGER PRIMARY KEY, inspection_id INTEGER NOT NULL REFERENCES inspections(id), item_code TEXT NOT NULL, result TEXT CHECK(result IN ('good','deficient','na')), comment TEXT, not_applicable_reason TEXT, UNIQUE(inspection_id,item_code));
CREATE TABLE findings(id INTEGER PRIMARY KEY, equipment_id INTEGER NOT NULL REFERENCES equipment(id), source_inspection_id INTEGER NOT NULL REFERENCES inspections(id), item_code TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', resolved_at TEXT, resolved_by INTEGER REFERENCES users(id), resolution_comment TEXT);
CREATE TABLE finding_events(id INTEGER PRIMARY KEY, finding_id INTEGER NOT NULL REFERENCES findings(id), event_type TEXT NOT NULL, actor_id INTEGER NOT NULL REFERENCES users(id), occurred_at TEXT DEFAULT CURRENT_TIMESTAMP, details TEXT);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, before_json TEXT, after_json TEXT, occurred_at TEXT DEFAULT CURRENT_TIMESTAMP);
COMMIT;
